import json, time, sys, urllib.request, urllib.error
BASE="http://localhost:8080"
tok=None
log=open("/tmp/recon/log.txt","w")
def new_token():
    global tok
    r=urllib.request.urlopen(urllib.request.Request(BASE+"/token",method="POST",data=b""))
    tok=json.load(r)["token"]; log.write(f"token {tok}\n")
def get(path):
    for attempt in range(200):
        if tok is None: new_token()
        req=urllib.request.Request(BASE+path,headers={"Authorization":"Bearer "+tok})
        try:
            r=urllib.request.urlopen(req,timeout=30)
            body=r.read()
            try: return 200, json.loads(body)
            except Exception as e:
                log.write(f"{path} bad json {body[:200]!r}\n"); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body=e.read()[:300]; h=dict(e.headers)
            log.write(f"{path} {e.code} {h} {body!r}\n"); log.flush()
            if e.code==401: new_token(); continue
            if e.code==429:
                ra=e.headers.get("Retry-After")
                time.sleep(float(ra) if ra else 1); continue
            if e.code==404: return 404, None
            time.sleep(0.5); continue
        except Exception as e:
            log.write(f"{path} exc {e!r}\n"); time.sleep(0.5); continue
    raise SystemExit("gave up "+path)
pages={}
p=1; total=None
path="/orders?page=1"
while path:
    c,d=get(path)
    pages[d["page"]]=d
    total=d["total_pages"]
    log.write(f"page {d['page']} items {len(d['items'])} next {d['next']}\n"); log.flush()
    path=d["next"]
missing=[i for i in range(1,total+1) if i not in pages]
log.write(f"missing after next-chain: {missing}\n")
for i in missing:
    c,d=get(f"/orders?page={i}"); pages[d["page"]]=d
json.dump(pages,open("/tmp/recon/pages.json","w"))
ids=set(); 
for d in pages.values():
    for o in d["items"]: ids.add(o["customer_id"])
cust={}
for cid in sorted(ids):
    c,d=get(f"/customers/{cid}")
    cust[cid]=d
json.dump(cust,open("/tmp/recon/customers.json","w"))
print("done", len(pages), total, len(cust))
EOF
cd /tmp/recon && python3 -I fetch.py; tail -40 log.txt; grep -c . log.txt

